-- Batch 10 — evidence-bounded editorial corrections to the second Lots-family cohort.
-- Text read in Abū Maʿshar, The Great Introduction, Part VIII §§4.14, 4.31–4.43, 4.70–4.83 and §6.12–6.15.
-- Deliberately no changes to formula tables or previous historical witness records; source conflicts remain unresolved.
PRAGMA foreign_keys=ON;

UPDATE term_articles SET intro='Abū Maʿshar (§4.42) describes this general Hermetic marriage lot separately from the male- and female-marriage lots. Its endpoint is the ''cardine of the wedding''; one textual witness interprets that cardine as the western angle and another explicitly as the seventh. These glosses should be recorded without replacing the phrase in the main formula.',editorial_notes='Batch 10: source-specific Lot distinction or removal of repeated introductory wording.' WHERE term_id=(SELECT id FROM terms WHERE slug='hermes-general-lot-of-marriage');
UPDATE term_articles SET intro='Abū Maʿshar gives a Hermes-attributed Enemies Lot distinct from the fixed Saturn–Mars lot ascribed to some Ancients. In §4.83 the arc ends at the degree of the enemies place, but the summary in §6.15 reads the degree of the ascendant. This discrepancy between his two accounts is unresolved; the displayed formula follows §4.83, and it should not be presented as a universal rule.',editorial_notes='Batch 10: source-specific Lot distinction or removal of repeated introductory wording.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-enemies-hermes');
UPDATE term_articles SET intro='In §4.31 Abū Maʿshar attributes the fixed Saturn-to-Venus construction to Hermes for the marriage of men. He also reports a nocturnally reversed alternative and explicitly prefers the fixed Hermetic order. The alternative is not a second night formula silently substituted into the Hermetic rule.',editorial_notes='Batch 10: source-specific Lot distinction or removal of repeated introductory wording.' WHERE term_id=(SELECT id FROM terms WHERE slug='hermes-lot-of-marriage-men');
UPDATE term_articles SET intro='For the marriage of women, Abū Maʿshar (§4.36) attributes a fixed Venus-to-Saturn construction to Hermes. It reverses the endpoints of the Hermetic men''s marriage lot, but neither formula reverses solely because the nativity is nocturnal.',editorial_notes='Batch 10: source-specific Lot distinction or removal of repeated introductory wording.' WHERE term_id=(SELECT id FROM terms WHERE slug='hermes-lot-of-marriage-women');
UPDATE term_articles SET intro='Abū Maʿshar (§4.32) attributes to Wālīs a fixed Sun-to-Venus marriage lot for men, whereas his Hermes account uses Saturn-to-Venus. These two calculations share an endpoint and topic but should remain separate historical formulas.',editorial_notes='Batch 10: source-specific Lot distinction or removal of repeated introductory wording.' WHERE term_id=(SELECT id FROM terms WHERE slug='walis-lot-of-marriage-men');
UPDATE term_articles SET intro='In §4.37 Abū Maʿshar attributes to Wālīs the fixed Moon-to-Mars marriage lot for women. He also reports a nocturnal reversal attributed to some Persians, but prefers Wālīs'' non-reversing rule. That competing variant must not overwrite the principal Wālīs formula.',editorial_notes='Batch 10: source-specific Lot distinction or removal of repeated introductory wording.' WHERE term_id=(SELECT id FROM terms WHERE slug='walis-lot-of-marriage-women');
UPDATE term_articles SET intro='Abū Maʿshar''s marriage section (§§4.31–4.43) preserves separate Hermes-attributed Lots for men, women, marriage generally and the time of marriage. They are distinguished by endpoints and purpose: this headword connects those entries rather than defining a new single formula.',editorial_notes='Batch 10: source-specific Lot distinction or removal of repeated introductory wording.' WHERE term_id=(SELECT id FROM terms WHERE slug='hermes-lot-of-marriage');
UPDATE term_articles SET intro='This is an editorial umbrella, not a historical formula by itself. Abū Maʿshar (§§4.82–4.83) gives one fixed Saturn-to-Mars Enemies Lot attributed to some Ancients and a second based on the lord and degree of the twelfth place attributed to Hermes. Other Saturn/Fortune traditions must be attributed independently rather than inserted as if they were his first formula.',editorial_notes='Batch 10: source-specific Lot distinction or removal of repeated introductory wording.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-enemies');
UPDATE term_articles SET intro='Abū Maʿshar (§4.14) gives the normal sect-reversed Sun–Saturn construction and substitutes Jupiter for Saturn when Saturn is under the rays. He additionally reports an alternative Mars–Jupiter construction under that condition but rejects it in favour of the Hermetic Sun–Jupiter account. The distinction affects how competing manuscript and authorial variants should be documented.',editorial_notes='Batch 10: source-specific Lot distinction or removal of repeated introductory wording.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-father');
UPDATE term_articles SET intro='The mother lot in Abū Maʿshar (§4.70) measures from Venus to the Moon by day, reverses at night and is projected from the Ascendant. He files it with the tenth place because the tenth stands opposite the fourth place of the father; this is a topical ordering, not a different calculation.',editorial_notes='Batch 10: source-specific Lot distinction or removal of repeated introductory wording.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-mother');
UPDATE term_articles SET intro='Abū Maʿshar''s Journey Lot (§6.12a) belongs to the ruler-to-place family of constructions and uses the ninth place without sect reversal. His immediately following Travel on Water Lot uses a different Saturn-to-15° Cancer arc and does reverse at night; the two journeys are therefore separate calculations.',editorial_notes='Batch 10: source-specific Lot distinction or removal of repeated introductory wording.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-travel');
UPDATE term_articles SET intro='',editorial_notes='Batch 10: source-specific Lot distinction or removal of repeated introductory wording.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-success');
UPDATE term_articles SET intro='Authority, rulership, occupation, support and high rank are distinct indexed lots in Abū Maʿshar''s tenth-place catalogue (§6.13). This editorial headword groups the overlapping English topics without imposing one degree formula on all the source-specific entries.',editorial_notes='Batch 10: source-specific Lot distinction or removal of repeated introductory wording.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-authority');
UPDATE term_articles SET intro='Abū Maʿshar (§6.13) counts this Saturn-to-Moon lot in the same direction by day and night. The subject combines social standing with the work or craft done by the native; it must not be collapsed into the authority-and-victory lot, which instead uses a Sun–Saturn arc and changes under the rays.',editorial_notes='Batch 10: source-specific Lot distinction or removal of repeated introductory wording.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-authority-and-occupation');
UPDATE term_articles SET intro='This distinct tenth-place lot (§6.13) shares its ordinary Sun–Saturn arc and Jupiter substitution with the Lot of the Father, but Abū Maʿshar assigns it a different topical purpose. Sharing a formula does not make the two indexed lots identical.',editorial_notes='Batch 10: source-specific Lot distinction or removal of repeated introductory wording.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-authority-support-victory');
UPDATE term_articles SET intro='',editorial_notes='Batch 10: source-specific Lot distinction or removal of repeated introductory wording.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-heavy-saturn');
UPDATE term_articles SET intro='Abū Maʿshar (§4.71) derives this eleventh-place lot from Fortune and Absence and connects it with honour, standing and enduring public regard. He also says it agrees with other named lots, including the Venus lot. Such an agreement in a particular transmitted arrangement should not erase the separate names and topics.',editorial_notes='Batch 10: source-specific Lot distinction or removal of repeated introductory wording.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-honour');
UPDATE term_articles SET intro='This tenth-place lot in Abū Maʿshar (§6.13) uses a Mars-to-Moon arc with nocturnal reversal. It is distinct from the fixed Saturn-to-Moon Authority and Occupation Lot and the Sun–Saturn Authority, Support and Victory Lot; similar titles do not license exchanging the endpoints.',editorial_notes='Batch 10: source-specific Lot distinction or removal of repeated introductory wording.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-rulership-and-authority');
UPDATE term_articles SET intro='The planetary Mars lot belongs to Abū Maʿshar''s seven-planet list and has a different construction from his additional courage, violence and combat lot. Historical titles overlap in meaning; the indexed formula and its source place are what distinguish these two entries.',editorial_notes='Batch 10: source-specific Lot distinction or removal of repeated introductory wording.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-mars-courage');
UPDATE term_article_sections SET heading='A preferred rule and a rejected alternative',body='In §4.14 Abū Maʿshar says Saturn under the Sun''s rays is replaced by Jupiter, yielding Sun-to-Jupiter by day and the reverse at night. He also reports a rival Mars-to-Jupiter extraction for that circumstance and judges it less correct than the Hermetic Sun-to-Jupiter rule. The displayed calculation follows his preferred rule; recording the rival account does not replace it.',editorial_notes='Batch 10: checked source conflict or author-specific alternative preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-father') AND section_key='substitution';
UPDATE term_article_sections SET heading='Hermes'' formula and a differing recap',body='The displayed fixed calculation follows Abū Maʿshar §4.83: Ascendant + (degree of twelfth place − lord of twelfth place). The summary in §6.15 instead says that the arc runs to the degree of the ascendant. The texts are internally divergent on that endpoint. Preserve the §4.83 formula as explicitly attributed and flag §6.15 for textual/source collation rather than silently ''correcting'' either witness.',editorial_notes='Batch 10: checked source conflict or author-specific alternative preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-enemies-hermes') AND section_key='formula';
UPDATE term_article_sections SET heading='Hermes'' fixed twelfth-place construction',body='In §4.83 Abū Maʿshar attributes the fixed twelfth-place calculation to Hermes: Ascendant + degree of twelfth place − ruler of twelfth place. A later summary (§6.15) instead mentions the ascendant as the endpoint; this textual discrepancy is not resolved here. Keep Hermes'' account distinct both from the Ancients'' Saturn–Mars lot and from unrelated Fortune–Saturn variants.',editorial_notes='Batch 10: checked source conflict or author-specific alternative preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='lot-of-enemies') AND section_key='formula-2';
